// One Overpass query per country due. One query for all six timed out on the
// public instance; one per country takes 10-60 s.
return $input.all().map((item) => ({ json: { iso: item.json.iso, query:
  '[out:json][timeout:120];area["ISO3166-1"="' + item.json.iso + '"][admin_level=2]->.a;(' +
  'nwr["office"]["website"](area.a);nwr["shop"]["website"](area.a);' +
  'nwr["office"]["contact:website"](area.a);nwr["shop"]["contact:website"](area.a););out tags;' } }));

// Decide which Overpass responses are good enough to use and to keep.
//
// Fetch OSM answers one item per OSM Queries item, in order. A failure is an
// item with an error and no data. Overpass can also answer 200 with a "remark"
// saying the query ran out of time, and whatever elements it managed: that is
// a partial country, and keeping it would replace a full snapshot with a
// fraction of one. Only a complete, non-empty response counts as fresh.
const asked = $('OSM Queries').all();
const got = $input.all();
return asked.map((a, i) => {
  const iso = a.json.iso;
  const raw = got[i] && got[i].json && got[i].json.data;
  let elements = null;
  let problem = null;
  if (!iso) problem = 'disabled';
  else if (!raw) problem = (got[i] && got[i].json && got[i].json.error && got[i].json.error.message) || 'no response';
  else {
    try {
      const body = JSON.parse(raw);
      if (body.remark && /error|timed out|runtime/i.test(body.remark)) problem = 'incomplete: ' + body.remark.slice(0, 120);
      else if (!Array.isArray(body.elements) || body.elements.length === 0) problem = 'no elements';
      else elements = body.elements.length;
    } catch (e) { problem = 'not JSON'; }
  }
  return { json: { iso, data: problem ? null : raw, elements, problem } };
});
